require_once __DIR__.'/../../config/session_guard.php';require_once __DIR__.'/../../config/config.php';require_role('SAD');
$usuario=current_user();$initials=get_initials($usuario['nombre']);$base=get_base_path();$logout_url=$base.'controllers/AuthController.php?action=logout';$role_label='Super Administrador';$role_class='role-sad';$avatar_class='avatar-sad';$header_sub='Revisión de solicitud';$_page='SolicitudesRegistro.php';
$idSolicitud=(int)($_GET['id']??0);$solicitud=null;try{$conexion=(new Database())->getConnection();$consulta=$conexion->prepare("SELECT s.*,u.nombre AS nombre_solicitante,u.correo AS correo_solicitante FROM solicitudes_establecimiento s LEFT JOIN usuarios u ON u.id=s.id_usuario_solicitante WHERE s.id=? LIMIT 1");$consulta->execute([$idSolicitud]);$solicitud=$consulta->fetch(PDO::FETCH_ASSOC)?:null;}catch(Throwable $error){error_log('No se pudo cargar solicitud: '.$error->getMessage());}
if($solicitud===null){http_response_code(404);header('Location: SolicitudesRegistro.php');exit;}
$tieneUbicacion=$solicitud['latitud']!==null&&$solicitud['longitud']!==null;$origen=!empty($solicitud['id_usuario_solicitante'])?'ADM registrado':'Solicitud pública';
$evidencias=[];foreach([1,2] as $numero){$contenido=(string)($solicitud['evidencia_'.$numero]??'');if($contenido==='')continue;$nombre=(string)($solicitud['evidencia_'.$numero.'_nombre']??('Evidencia '.$numero));$evidencias[]=['nombre'=>$nombre,'contenido'=>$contenido,'tipo'=>str_starts_with($contenido,'data:application/pdf')||str_ends_with(mb_strtolower($nombre),'.pdf')?'pdf':'imagen'];}
