<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RetinAI — Detalle de solicitud</title><link rel="stylesheet" href="<?= $base ?>assets/css/dashboard/dashboard.css"><link rel="stylesheet" href="<?= $base ?>assets/css/dashboard/paneles.css"><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><script defer src="<?= $base ?>assets/js/superadmin_evidencias.js"></script></head><body><?php require_once __DIR__.'/../shared/header.php'; ?><div class="app-shell"><?php require_once __DIR__.'/../shared/sidebar.php'; ?><main class="main-content">
<header class="panel-cabecera"><div><a class="text-muted text-sm" href="SolicitudesRegistro.php">← Solicitudes</a><h1 class="page-title" style="margin-top:8px"><?= htmlspecialchars($solicitud['nombre_centro']) ?></h1><p class="page-sub">Expediente de registro #<?= (int)$solicitud['id'] ?></p></div><span class="etiqueta-estado etiqueta-<?= htmlspecialchars($solicitud['estado']) ?>"><?= htmlspecialchars(ucfirst($solicitud['estado'])) ?></span></header>
<div class="detalle-rejilla"><div class="panel-lista">
<section class="panel-tarjeta"><div class="panel-titulo"><h2>Datos del establecimiento</h2></div><div class="detalle-datos"><?php foreach([['Nombre',$solicitud['nombre_centro']],['RUC',$solicitud['ruc']],['Tipo',ucfirst($solicitud['tipo'])],['Dirección',$solicitud['direccion']],['Origen',$origen],['Fecha',date('d/m/Y H:i',strtotime($solicitud['fecha_solicitud']))]] as $dato): ?><div class="detalle-dato"><span><?= htmlspecialchars($dato[0]) ?></span><strong><?= htmlspecialchars($dato[1]) ?></strong></div><?php endforeach; ?></div></section>
<section class="panel-tarjeta"><div class="panel-titulo"><h2>Titular</h2></div><div class="detalle-datos"><?php foreach([['Nombre',$solicitud['nombres_titular'].' '.$solicitud['apellidos_titular']],['DNI',$solicitud['dni_titular']],['Teléfono',$solicitud['telefono']],['Correo',$solicitud['correo_contacto']]] as $dato): ?><div class="detalle-dato"><span><?= htmlspecialchars($dato[0]) ?></span><strong><?= htmlspecialchars($dato[1]) ?></strong></div><?php endforeach; ?></div></section>
</div><section class="panel-tarjeta"><div class="panel-titulo"><h2>Ubicación</h2></div><?php if($tieneUbicacion): ?><div class="mapa-detalle" id="mapa-solicitud"></div><div class="mapa-acciones"><span class="mapa-coordenadas"><?= htmlspecialchars(number_format((float)$solicitud['latitud'],6,'.','')) ?>, <?= htmlspecialchars(number_format((float)$solicitud['longitud'],6,'.','')) ?></span><a class="btn btn-secondary btn-sm" href="https://www.google.com/maps/search/?api=1&amp;query=<?= rawurlencode((string)$solicitud['latitud'].','.(string)$solicitud['longitud']) ?>" target="_blank" rel="noopener noreferrer">Abrir ubicación en mapa externo</a></div><?php else: ?><div class="estado-vacio">La solicitud no incluye coordenadas confirmadas.</div><?php endif; ?></section></div>
<section class="panel-tarjeta" style="margin-top:18px"><div class="panel-titulo"><h2>Evidencias del establecimiento</h2></div><?php if($evidencias===[]): ?><div class="estado-vacio">No se adjuntaron evidencias.</div><?php else: ?><div class="visor-evidencias"><nav class="lista-evidencias" aria-label="Archivos de evidencia"><?php foreach($evidencias as $indice=>$evidencia): ?><button class="evidencia-selector<?= $indice===0?' activa':'' ?>" type="button" data-evidencia="<?= $indice ?>" title="<?= htmlspecialchars($evidencia['nombre']) ?>"><?php if($evidencia['tipo']==='pdf'): ?><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M6 2h8l4 4v16H6z" stroke="currentColor" stroke-width="1.7"/><path d="M14 2v5h5M8.5 16h7M8.5 12h7" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/></svg><?php else: ?><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><rect x="3" y="4" width="18" height="16" rx="2" stroke="currentColor" stroke-width="1.7"/><circle cx="9" cy="10" r="2" stroke="currentColor" stroke-width="1.7"/><path d="m5 18 5-5 3 3 2-2 4 4" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/></svg><?php endif; ?><span class="evidencia-selector__texto"><span class="evidencia-selector__nombre"><?= htmlspecialchars($evidencia['nombre']) ?></span><span class="evidencia-selector__tipo"><?= $evidencia['tipo']==='pdf'?'Documento PDF':'Imagen adjunta' ?></span></span></button><?php endforeach; ?></nav><div class="visor-evidencia"><div class="visor-evidencia__cabecera"><strong class="visor-evidencia__nombre" id="evidencia-nombre"></strong><a class="btn btn-secondary btn-sm" id="evidencia-abrir" target="_blank" rel="noopener noreferrer">Abrir en una pestaña</a></div><div class="visor-evidencia__contenido"><img id="evidencia-imagen" alt="Evidencia seleccionada"><iframe id="evidencia-pdf" title="Documento PDF de evidencia"></iframe></div></div></div><?php endif; ?></section>
<?php if($solicitud['estado']==='pendiente'): ?><div class="acciones-detalle"><form method="post" action="<?= $base ?>controllers/SolicitudController.php"><input type="hidden" name="action" value="rechazar"><input type="hidden" name="id" value="<?= (int)$solicitud['id'] ?>"><button class="btn btn-danger" type="submit" onclick="return confirm('¿Rechazar esta solicitud?')">Rechazar</button></form><form method="post" action="<?= $base ?>controllers/SolicitudController.php"><input type="hidden" name="action" value="aprobar"><input type="hidden" name="id" value="<?= (int)$solicitud['id'] ?>"><button class="btn btn-primary" type="submit" onclick="return confirm('¿Aprobar esta solicitud?')">Aprobar establecimiento</button></form></div><?php endif; ?>
</main></div><?php if($tieneUbicacion): ?><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const latitud=<?= json_encode((float)$solicitud['latitud']) ?>,longitud=<?= json_encode((float)$solicitud['longitud']) ?>,mapa=L.map('mapa-solicitud').setView([latitud,longitud],16);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'OpenStreetMap'}).addTo(mapa);L.marker([latitud,longitud]).addTo(mapa).bindPopup(<?= json_encode($solicitud['nombre_centro'],JSON_UNESCAPED_UNICODE) ?>).openPopup();</script><?php endif; ?><?php if($evidencias!==[]): ?><script>const evidencias=<?= json_encode($evidencias,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>,nombreEvidencia=document.getElementById('evidencia-nombre'),abrirEvidencia=document.getElementById('evidencia-abrir'),imagenEvidencia=document.getElementById('evidencia-imagen'),pdfEvidencia=document.getElementById('evidencia-pdf');function mostrarEvidencia(indice){const evidencia=evidencias[indice];if(!evidencia)return;document.querySelectorAll('[data-evidencia]').forEach((boton,posicion)=>boton.classList.toggle('activa',posicion===indice));nombreEvidencia.textContent=evidencia.nombre;abrirEvidencia.href=evidencia.contenido;if(evidencia.tipo==='pdf'){imagenEvidencia.style.display='none';imagenEvidencia.removeAttribute('src');pdfEvidencia.src=evidencia.contenido;pdfEvidencia.style.display='block'}else{pdfEvidencia.style.display='none';pdfEvidencia.removeAttribute('src');imagenEvidencia.src=evidencia.contenido;imagenEvidencia.style.display='block'}}document.querySelectorAll('[data-evidencia]').forEach(boton=>boton.addEventListener('click',()=>mostrarEvidencia(Number(boton.dataset.evidencia))));mostrarEvidencia(0);</script><?php endif; ?></body></html>
